"""Compact CSS for the independent Lightsail control page."""
STYLE = """
:root{--bg:#080d14;--panel:#121a25;--line:#263447;--text:#e6edf3;--mut:#91a0b2;--green:#198754;--amber:#b77908;--blue:#2563eb}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,Segoe UI,sans-serif}.top{position:sticky;top:0;z-index:3;padding:11px 16px;background:#0c1420;border-bottom:1px solid var(--line);display:flex;gap:10px;align-items:center}.top b{font-size:16px}.sp{flex:1}.wrap{max-width:920px;margin:14px auto;padding:0 12px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:7px}.card{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:14px;margin-bottom:11px}.k{font-size:10px;text-transform:uppercase;color:var(--mut)}.v{font-size:17px;font-weight:750;margin-top:3px;overflow:hidden;text-overflow:ellipsis}h2{font-size:15px;margin:0 0 5px}p{color:var(--mut);margin:4px 0 11px;line-height:1.4}label{display:block;color:var(--mut);font-size:12px;margin:9px 0 4px}input{width:100%;padding:9px;background:#090f18;color:var(--text);border:1px solid var(--line);border-radius:8px}button,.btn{display:inline-block;margin:7px 5px 0 0;padding:9px 13px;border:0;border-radius:8px;color:white;background:var(--blue);font-weight:650;text-decoration:none;cursor:pointer}.amber{background:var(--amber)}.green{background:var(--green)}.gray{background:#364152}.row{display:flex;gap:6px;flex-wrap:wrap}.flash{padding:9px;border-radius:8px;margin-bottom:9px}.ok{background:#0e2c20;color:#8ff0bc}.warn{background:#332a10;color:#ffe29a}.bad{background:#35151c;color:#ffc1cb}small{color:var(--mut)}
"""
